using System;using UnityEngine;
namespace LWS.TruckSumo.Editor {
public static class SumoFixtures {
 public static void Run(){int checks=0;Action<bool,string> check=(value,name)=>{if(!value)throw new Exception("Sumo fixture: "+name);checks++;};var rules=new SumoRules();rules.Reset(4);rules.Crossed(0);check(!rules.FinishStep()&&rules.alive[1],"one eliminated body does not end four-truck heat");rules.Crossed(1);rules.Crossed(2);rules.Crossed(3);check(rules.FinishStep()&&rules.HeatWinner==-1&&Array.TrueForAll(rules.wins,n=>n==0),"entire final same-step batch gives draw, no accidental point");check(!rules.Crossed(0)&&!rules.FinishStep(),"duplicate callbacks cannot refinalize heat");rules.Reset(2);for(int i=0;i<5;i++){rules.Crossed(1);check(rules.FinishStep()&&rules.HeatWinner==0&&rules.wins[0]==i+1,"one point per sole-survivor heat");if(i<4)rules.NextHeat();}check(rules.Complete&&rules.Winner==0&&rules.Heat==5,"first to five finishes match");rules.Reset(3);rules.TimeoutDraw();check(rules.Resolved&&rules.HeatWinner==-1&&Array.TrueForAll(rules.wins,n=>n==0),"bounded unresolved heat is explicit no-point draw");check(!SumoRules.Outside(12,0,12)&&SumoRules.Outside(12.001f,0,12),"body-center boundary has inclusive visible edge, no wheel footprint test");check(!SumoRules.Outside(0,0,5),"airborne body inside legal XZ is not ring-out");Debug.Log("SUMO_RULE_FIXTURES_PASS "+checks);}
}
}
